/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_CLAIM_STATUS_TRANSITION
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_CLAIM   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : (not declared in data_7.js)
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_v2
   payload     : 4 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_CLAIM_HK
   hashdiff    : SAT_CLAIM_STATUS_TRANSITION_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , UPDATED_BY as TRANSITION_ACTOR_USER_REFERENCE
        , VERSION_NO as CLAIM_RECORD_VERSION_NUMBER
        , PREV_CLAIM_STATUS as PREVIOUS_CLAIM_STATUS_CODE
        , PROCESS_NAME as WORKFLOW_PROCESS_NAME
        , 'BJAZ_HM_CLAIM_TRACKER' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_claim_tracker') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
),

resolved as (
    select
        HUB_CLAIM_HK,
        max(case when SOURCE_RUN = 'opus_health_v2' then TRANSITION_ACTOR_USER_REFERENCE end) as TRANSITION_ACTOR_USER_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_v2' then CLAIM_RECORD_VERSION_NUMBER end) as CLAIM_RECORD_VERSION_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_v2' then PREVIOUS_CLAIM_STATUS_CODE end) as PREVIOUS_CLAIM_STATUS_CODE,
        max(case when SOURCE_RUN = 'opus_health_v2' then WORKFLOW_PROCESS_NAME end) as WORKFLOW_PROCESS_NAME,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK
),

hashed as (
    select
        *,
        case when TRANSITION_ACTOR_USER_REFERENCE is not null or CLAIM_RECORD_VERSION_NUMBER is not null or PREVIOUS_CLAIM_STATUS_CODE is not null or WORKFLOW_PROCESS_NAME is not null
                     then md5(upper(coalesce(cast(TRANSITION_ACTOR_USER_REFERENCE as varchar), '') || '|' || coalesce(cast(CLAIM_RECORD_VERSION_NUMBER as varchar), '') || '|' || coalesce(cast(PREVIOUS_CLAIM_STATUS_CODE as varchar), '') || '|' || coalesce(cast(WORKFLOW_PROCESS_NAME as varchar), '')))
                end as SAT_CLAIM_STATUS_TRANSITION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_STATUS_TRANSITION_HASHDIFF is not null
